const SPHINX = "sphinx";
const SPHINX_SCORE = 2;
const NO_SPHINX_SCORE = 0;

export const scoreArmy = (army: Card[]): number =>
  army.some((card) => card.monster === SPHINX) ? SPHINX_SCORE : NO_SPHINX_SCORE;
